/bin/zsh -lc "node <<'NODE'
const fs = require('fs');
const obj = JSON.parse(fs.readFileSync('output/analysis.json', 'utf8'));
const md = fs.readFileSync('output/analysis.md', 'utf8');
const required = ['status','analysis_summary','preliminary_requirement_markdown','analysis_report_markdown','applied_supplements','maturity_assessment','key_gaps','assumptions','modules','clarification_questions','conflicts','coverage_audit','quality_gate','next_actions'];
const missing = required.filter(k => "'!(k in obj));
console.log('"'analysis.json parse: ok');
console.log('missing fields:', missing.length ? missing.join(', ') : 'none');
console.log('markdown equality:', obj.analysis_report_markdown === md ? 'ok' : 'mismatch');
console.log('clarification_questions:', obj.clarification_questions.length);
console.log('conflicts:', obj.conflicts.length);
console.log('applied_supplements:', obj.applied_supplements.length);
NODE
ls -l output/analysis.json output/analysis.md"

